    const result = {};
    files.forEach(f => {
      const m = f.match(/wang__v(\d+)/);
      if (m) result[parseInt(m[1])] = 'assets/pixelab/landscape_v2/base/' + name.replace(/_/g, '/') + '/wang/' + f;
